#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn actions_parse_with_the_expected_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 52, "harvested length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort();
        names.dedup();
        assert_eq!(names.len(), n, "names unique");
        // Every row carries a dispatchable step list — an action with no steps is unreachable.
        for x in a {
            let steps = x["steps_json"].as_str().expect("steps_json is a string");
            assert!(steps.contains("skill"), "{} has no skill step", x["name"]);
        }
    }

    #[test]
    fn the_routes_the_BE_dispatches_are_present() {
        // These 404'd on a fresh workspace before this shard existed.
        let v: &Value = &ACTIONS;
        let names: Vec<&str> = v.as_array().unwrap().iter().map(|x| x["name"].as_str().unwrap()).collect();
        for want in [
            "system.cards.active", "system.drift.list", "system.card.metrics",
            "system.card.process.events", "system.card.discuss", "system.reconcile.apply",
        ] {
            assert!(names.contains(&want), "{want} is missing");
        }
    }
}
